reference_solution:
def checkInclusion(s1, s2):
    n, m = len(s1), len(s2)
    if n > m:
        return False
    need = [0] * 26
    win = [0] * 26
    for ch in s1:
        need[ord(ch) - 97] += 1
    for i in range(m):
        win[ord(s2[i]) - 97] += 1
        if i >= n:
            win[ord(s2[i - n]) - 97] -= 1
        if win == need:
            return True
    return False

brute_force_solution:
def checkInclusion(s1, s2):
    n = len(s1)
    return any(sorted(s2[i:i + n]) == sorted(s1) for i in range(len(s2) - n + 1))

